15	/** Squared distance from the claim point, refusing coordinates whose square would not be an exact integer. */
16	export function claimDistanceSquared(config: ClaimConfig, x: number, y: number): number {
17	  const dx = x - config.claimPoint.x;
18	  const dy = y - config.claimPoint.y;
19	  const squared = dx * dx + dy * dy;
20	  if (!Number.isSafeInteger(squared)) throw new RangeError(`position (${x}, ${y}) is too far from the claim point`);
21	  return squared;
22	}
23	
24	export function insideTreasureCircle(config: ClaimConfig, x: number, y: number): boolean {
25	  return claimDistanceSquared(config, x, y) <= config.circleRadius * config.circleRadius;
26	}
27	
28	/**
29	 * Whether a player meets §5's conditions to start claiming on this tick, protection aside: starting ends protection
30	 * (§6), so a protected player may start. A player can wait with interact held; this does not say a channel is free.
31	 */
32	export function canStartClaim(config: ClaimConfig, player: ClaimPlayer, reserved: boolean): boolean {
33	  return (
34	    player.connected &&
35	    player.holdsAllTypes &&
36	    player.interact &&
37	    !reserved &&
38	    player.speed === 0 &&
39	    insideTreasureCircle(config, player.x, player.y)
40	  );
41	}
42	
43	/** Why the active channel cannot continue on this tick, or null. Reservations are checked before this. */
44	function channelBreak(channel: ClaimChannel, player: ClaimPlayer | undefined): ClaimInterruptReason | null {
45	  if (player === undefined || !player.connected) return "disconnected";
46	  if (!player.holdsAllTypes) return "ineligible";
47	  // The channel pins the position it started at, which lies inside the circle.
48	  if (player.speed !== 0 || player.x !== channel.x || player.y !== channel.y) return "moved";
49	  if (!player.interact) return "released";
50	  return null;
51	}
