1511	        if (synced === undefined) {
1512	          synced = new GrappleSchema();
1513	          synced.attackerId = attempt.attackerId;
1514	          this.state.grapples.set(key, synced);
1515	        }
1516	        synced.defenderId = defenderId;
1517	        synced.aim = attempt.aim;
1518	        synced.startTick = attempt.startTick;
1519	        synced.landTick = attempt.landTick;
1520	      }
1521	    }
1522	    for (const key of [...this.state.grapples.keys()]) if (!keys.has(key)) this.state.grapples.delete(key);
1523	
1524	    const records = new Map(this.encounters.players.map((player) => [player.id, player]));
1525	    for (const id of present) {
