1528	        status = new PlayerStatusSchema();
1529	        this.state.status.set(id, status);
1530	      }
1531	      const record = records.get(id);
1532	      status.mode = record?.respawn != null ? "respawning" : duelOf(this.encounters, id) !== undefined ? "duel" : "sea";
1533	      status.protection = record?.protection?.source ?? "";
1534	      status.protectedUntil = record?.protection?.endTick ?? 0;
1535	      status.cooldownUntil = record?.cooldownEndTick ?? 0;
1536	      status.respawnAt = record?.respawn?.respawnTick ?? 0;
1537	    }
1538	    for (const id of [...this.state.status.keys()]) if (!present.has(id)) this.state.status.delete(id);
