1546	  private mirrorObjectives(present: ReadonlySet<string>): void {
1547	    const map = this.config.map;
1548	    const ships = new Map(this.simulation.ships.map((ship) => [ship.id, ship]));
1549	    const held = this.heldPlayers();
1550	    for (const id of present) {
