1552	      const player = findPlayer(this.ledger, id);
1553	      const ship = ships.get(id)!;
1554	      const moored = ship.dock !== NOT_DOCKED && !held.has(id) && player !== undefined;
1555	      status.gold = player?.gold ?? 0;
1556	      status.rubbings = player === undefined ? "" : heldTypes(this.ledger, id).join(",");
1557	      status.islandTypes = moored ? sealedTypesAt(this.ledger, map.docks[ship.dock]!.island).join(",") : "";
1558	      status.cacheTypes = moored ? cachedTypesAt(this.ledger, map, ship.dock).join(",") : "";
1559	      const target = moored && player.status === "connected" ? interactTarget(this.ledger, map, id, ship.dock) : undefined;
1560	      status.target = target === undefined ? "" : `${target.kind}:${target.type}`;
1561	      const channel = player?.channel ?? null;
1562	      status.channel = channel?.kind ?? "";
1563	      status.channelType = channel === null ? "" : (this.ledger.rubbings.find((rubbing) => rubbing.id === channel.rubbingId)?.type ?? "");
